<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import { getCartStorageKey, readCart, writeCart, type CartItem } from '@/lib/cart';
type Product={id:number;slug:string;name:string;category:string;brand:string;price:number;oldPrice?:number|null;image?:string|null;gallery:string[];badge?:string|null;rating:number;sold:number;stock:number;shortDescription?:string|null;description?:string|null;specs:Record<string,string>;sku?:string;productType?:string|null;productLine?:string|null};type Review={id:number;rating:number;content:string;name:string;createdAt:string};
const p=defineProps<{product:Product|null;reviews:Review[];recommendations:Product[]}>();const product=computed(()=>p.product);const page=usePage();const selectedImage=ref(0);const quantity=ref(1);const added=ref(false);const reviews=ref<Review[]>([...(p.reviews??[])]);const deliveredOrders=ref<any[]>([]);const reviewOrder=ref('');const reviewRating=ref(5);const reviewText=ref('');const reviewError=ref('');
const userId=computed(()=>((page.props as any).auth?.user?.id??null) as number|null);
function addToCart(){if(!product.value||product.value.stock<1)return;const item:CartItem={id:product.value.id,name:product.value.name,price:product.value.price,image:product.value.image??'',quantity:Math.min(quantity.value,product.value.stock)};const cart=readCart(userId.value);const existing=cart.find(x=>x.id===item.id);if(existing)existing.quantity=Math.min(product.value.stock,existing.quantity+item.quantity);else cart.push(item);writeCart(userId.value,cart);added.value=true;window.setTimeout(()=>added.value=false,1500)}
function buyNow(){if(!product.value||product.value.stock<1)return;localStorage.setItem('techstore_buy_now',JSON.stringify({id:product.value.id,name:product.value.name,price:product.value.price,image:product.value.image??'',quantity:Math.min(quantity.value,product.value.stock)}));router.visit('/checkout?buy_now=1')}
function errorImage(e:Event){(e.target as HTMLImageElement).style.display='none'}
async function loadOrders(){if(!userId.value)return;try{const r=await fetch('/orders',{headers:{Accept:'application/json'}});const d=await r.json();deliveredOrders.value=(d.orders??[]).filter((o:any)=>o.status==='Đã giao'&&o.items?.some((i:any)=>i.id===product.value?.id))}catch{}}
async function submitReview(){if(!product.value||!reviewOrder.value||reviewText.value.trim().length<3){reviewError.value='Vui lòng chọn đơn hàng đã nhận và nhập nội dung đánh giá.';return}try{const token=document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??'';const r=await fetch(`/products/${product.value.id}/reviews`,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':token},body:JSON.stringify({order_id:Number(reviewOrder.value),rating:reviewRating.value,content:reviewText.value})});const d=await r.json();if(!r.ok)throw new Error(d.message??'Không thể gửi đánh giá.');reviews.value.unshift(d.review);reviewText.value='';reviewError.value=''}catch(e){reviewError.value=e instanceof Error?e.message:'Không thể gửi đánh giá.'}}
const stars=(n:number)=>'★'.repeat(n)+'☆'.repeat(5-n);const date=(v:string)=>new Intl.DateTimeFormat('vi-VN',{dateStyle:'medium'}).format(new Date(v));
onMounted(loadOrders);
</script>
<template><Head :title="product?.name||'Sản phẩm'"/><main v-if="product" class="product-detail-page"><div class="container product-detail-container"><nav class="detail-breadcrumb"><Link href="/">Trang chủ</Link><i class="bi bi-chevron-right"/><Link href="/products">Sản phẩm</Link><i class="bi bi-chevron-right"/><span>{{product.name}}</span></nav><section class="detail-card"><div class="row g-0"><div class="col-lg-6 detail-gallery-column"><div class="detail-main-image"><span v-if="product.badge" class="detail-image-badge">{{product.badge}}</span><img :src="product.gallery[selectedImage]||product.image||''" :alt="product.name" @error="errorImage"/><div class="detail-image-fallback"><i class="bi bi-laptop"/><span>{{product.brand}}</span></div></div><div class="detail-thumbs"><button v-for="(image,index) in product.gallery" :key="`${image}-${index}`" type="button" :class="['detail-thumb',{active:selectedImage===index}]" @click="selectedImage=index"><img :src="image" :alt="`${product.name} ${index+1}`"/></button></div></div><div class="col-lg-6 detail-info-column"><div class="detail-info"><div class="detail-category-line"><span class="detail-brand">{{product.brand}}</span><span>•</span><span>{{product.category}}</span><span v-if="product.productType">• {{product.productType}}</span></div><h1 class="detail-title">{{product.name}}</h1><div class="detail-rating-row"><span class="rating-item"><i class="bi bi-star-fill"/> {{product.rating.toFixed(1)}}</span><span>{{product.sold}} đã bán</span><span>Mã SP: {{product.sku||`TS-${String(product.id).padStart(4,'0')}`}}</span></div><p class="detail-description">{{product.shortDescription}}</p><div class="detail-price-box"><strong>{{formatPrice(product.price)}}</strong><del v-if="product.oldPrice">{{formatPrice(product.oldPrice)}}</del><span v-if="product.oldPrice" class="discount-pill">-{{Math.round((1-product.price/product.oldPrice)*100)}}%</span></div><div class="detail-stock"><span :class="{out:product.stock<1}"><i class="bi bi-check-circle-fill"/> {{product.stock<1?'Hết hàng':'Còn hàng'}}</span><b>{{product.stock}} sản phẩm</b></div><div class="detail-divider"/><div class="purchase-row"><div class="quantity-control"><button @click="quantity=Math.max(1,quantity-1)">−</button><span>{{quantity}}</span><button :disabled="quantity>=product.stock" @click="quantity=Math.min(product.stock,quantity+1)">+</button></div><button class="buy-now-btn" :disabled="product.stock<1" @click="buyNow"><i class="bi bi-lightning-fill"/> Mua ngay</button><button class="add-cart-btn" :class="{added}" :disabled="product.stock<1" @click="addToCart"><i :class="['bi',added?'bi-check-lg':'bi-cart-plus']"/> {{added?'Đã thêm':'Thêm giỏ'}}</button></div><div class="detail-benefits"><div class="benefit-item"><span class="benefit-icon"><i class="bi bi-shield-check"/></span><span><b>Chính hãng</b><small>Bảo hành theo nhà sản xuất</small></span></div><div class="benefit-item"><span class="benefit-icon"><i class="bi bi-truck"/></span><span><b>Giao hàng toàn quốc</b><small>Đóng gói an toàn, theo dõi đơn</small></span></div></div></div></div></div></section><section class="detail-lower-row row g-4"><div class="col-lg-8"><article class="detail-panel"><div class="panel-heading"><div><span>THÔNG TIN</span><h2>Thông tin sản phẩm</h2></div><i class="bi bi-info-circle"/></div><p class="product-description">{{product.description}}</p><div class="spec-grid"><div v-for="(value,key) in product.specs" :key="key" class="spec-item"><span>{{key}}</span><strong>{{value}}</strong></div></div></article></div><div class="col-lg-4"><article class="detail-panel"><div class="panel-heading"><div><span>TECHSTORE</span><h2>Cam kết</h2></div><i class="bi bi-patch-check"/></div><ul class="commit-list"><li><i class="bi bi-patch-check-fill"/>Sản phẩm chính hãng</li><li><i class="bi bi-box-seam"/>Đóng gói chống sốc</li><li><i class="bi bi-arrow-repeat"/>Hỗ trợ đổi trả</li><li><i class="bi bi-headset"/>Tư vấn kỹ thuật</li></ul></article></div></section><section class="detail-panel review-panel"><div class="panel-heading"><div><span>KHÁCH HÀNG</span><h2>Đánh giá sản phẩm</h2></div><strong>{{reviews.length}} đánh giá</strong></div><div v-if="deliveredOrders.length" class="review-form"><div><label>Đơn hàng đã nhận</label><select v-model="reviewOrder"><option value="">Chọn đơn hàng</option><option v-for="o in deliveredOrders" :key="o.id" :value="o.id">#{{o.code}}</option></select></div><div><label>Điểm</label><select v-model.number="reviewRating"><option :value="5">5 sao</option><option :value="4">4 sao</option><option :value="3">3 sao</option><option :value="2">2 sao</option><option :value="1">1 sao</option></select></div><textarea v-model="reviewText" rows="3" placeholder="Chia sẻ trải nghiệm của bạn..."/><div class="review-form-footer"><span v-if="reviewError" class="review-error">{{reviewError}}</span><button @click="submitReview">Gửi đánh giá</button></div></div><div v-if="reviews.length" class="reviews-list"><article v-for="r in reviews" :key="r.id"><div class="review-head"><strong>{{r.name}}</strong><span>{{stars(r.rating)}}</span><small>{{date(r.createdAt)}}</small></div><p>{{r.content}}</p></article></div><div v-else class="review-empty"><i class="bi bi-chat-square-heart"/><strong>Chưa có đánh giá</strong><span>Hãy là người đầu tiên chia sẻ trải nghiệm.</span></div></section><section v-if="recommendations.length" class="detail-panel"><div class="panel-heading"><div><span>GỢI Ý</span><h2>Sản phẩm thường mua cùng</h2></div><i class="bi bi-bag-heart"/></div><div class="recommend-grid"><Link v-for="item in recommendations" :key="item.id" :href="`/products/${item.slug}`" class="recommend-card"><img :src="item.image||''" :alt="item.name"/><div><span>{{item.brand}}</span><strong>{{item.name}}</strong><b>{{formatPrice(item.price)}}</b></div></Link></div></section></div></main><div v-else class="container py-5"><div class="empty-catalog"><i class="bi bi-box-seam"/><h3>Không tìm thấy sản phẩm</h3><Link href="/products" class="btn btn-primary mt-2">Quay lại sản phẩm</Link></div></div></template>
